// ===== Expected roles + who to notify if missing =====
const EXPECTED_DEPARTMENTS = [
  "Executive Assistant",
  "Graphics designer & Video Editor",
  "Creative Developer and Ministry Coordinator",
  "Creative Intern",
];

const DEPT_EMAIL = {
  "Executive Assistant": "growth@example.com",
  "Graphics designer & Video Editor": "media@example.com",
  "Creative Developer and Ministry Coordinator": "hello@example.com",
  "Creative Intern": "media@example.com",
};

// ===== Detect column keys from the sheet output =====
const keys = Object.keys(items[0]?.json || {});
const TS_COL = keys.find(k => k.toLowerCase().includes("timestamp")) || "Timestamp";
const DEPT_COL = keys.find(k => k.toLowerCase().includes("department")) || "Department/Role";
const LINK_COL = keys.find(k => k.toLowerCase().includes("link to weekly")) || "Link to weekly Report";
const SUBMITTED_COL = keys.find(k => k.toLowerCase().includes("submitted")) || "Submitted By;";
const MONTH_COL = keys.find(k => k.toLowerCase() === "month") || "Month";
const WEEK_COL = keys.find(k => k.toLowerCase() === "week") || "Week";

// ===== Window: last 2 days from execution time =====
const windowEnd = new Date($now);
const windowStart = new Date(windowEnd.getTime() - (2 * 24 * 60 * 60 * 1000));

// ===== Helpers =====
const fmtWAT = (d) => d.toLocaleString('en-GB', { timeZone: 'Africa/Lagos' });
const norm = (s) => String(s || "").trim().toLowerCase();

function parseTimestamp(s) {
  if (!s) return null;
  const str = String(s).trim();
  const [datePart, timePartRaw] = str.split(" ");
  if (!datePart) return null;

  const dParts = datePart.split("/");
  if (dParts.length !== 3) return null;

  // Sheet timestamps confirmed as MM/DD/YYYY
  const m = Number(dParts[0]);
  const d = Number(dParts[1]);
  const y = Number(dParts[2]);

  const timePart = timePartRaw || "00:00:00";
  const tParts = timePart.split(":");
  const hh = Number(tParts[0] || 0);
  const mm = Number(tParts[1] || 0);
  const ss = Number(tParts[2] || 0);

  // ✅ FIX: Build an ISO string with explicit WAT offset (+01:00)
  // so Date.parse() treats it as WAT, not local/UTC ambiguously
  const pad = (n) => String(n).padStart(2, "0");
  const isoString = `${y}-${pad(m)}-${pad(d)}T${pad(hh)}:${pad(mm)}:${pad(ss)}+01:00`;
  const dt = new Date(isoString);

  if (Number.isNaN(dt.getTime())) return null;
  return dt;
}

// ===== Step 1: inspect + filter by time window =====
const inspected = items.map(i => {
  const rawTs = i.json[TS_COL];
  const parsed = parseTimestamp(rawTs);
  return {
    ...i.json,
    __parsedMs: parsed ? parsed.getTime() : null,
  };
});

const filtered = inspected
  .filter(r => r.__parsedMs && r.__parsedMs > windowStart.getTime() && r.__parsedMs <= windowEnd.getTime())
  .sort((a, b) => a.__parsedMs - b.__parsedMs);

// ===== Step 2: use ALL filtered rows for management summary =====
let html = `
<p>Hello Management,</p>

<p>
Below is the summary of weekly reports submitted between
<strong>${fmtWAT(windowStart)}</strong> and
<strong>${fmtWAT(windowEnd)}</strong> (WAT).
</p>

<p><strong>Total submissions:</strong> ${filtered.length}</p>

<table border="1" cellpadding="6" cellspacing="0">
<tr>
  <th>Month</th>
  <th>Week</th>
  <th>Timestamp</th>
  <th>Department/Role</th>
  <th>Submitted By</th>
  <th>Report Link</th>
</tr>
`;

for (const r of filtered) {
  const link = (r[LINK_COL] || "").trim();
  const isUrl = /^https?:\/\//i.test(link);
  const linkCell = link
    ? (isUrl ? `<a href="${link}">Open report</a>` : link)
    : "";

  html += `<tr>
    <td>${r[MONTH_COL] || ""}</td>
    <td>${r[WEEK_COL] || ""}</td>
    <td>${r[TS_COL] || ""}</td>
    <td>${r[DEPT_COL] || ""}</td>
    <td>${r[SUBMITTED_COL] || ""}</td>
    <td>${linkCell}</td>
  </tr>`;
}

// ===== Step 3: after management summary, determine missing roles =====
const submittedRoles = filtered.map(r => r[DEPT_COL] || "");
const submittedRoleSet = new Set(submittedRoles.map(norm).filter(Boolean));

const missingRolesPretty = EXPECTED_DEPARTMENTS.filter(
  role => !submittedRoleSet.has(norm(role))
);

html += `</table>

<p><strong>Missing roles:</strong> ${missingRolesPretty.length ? missingRolesPretty.join(", ") : "None"}</p>

<p>Best regards,<br><strong>[Your Organization]</strong></p>`;

// ===== Step 4: output items =====
const outputItems = [];

// Management item
outputItems.push({
  json: {
    type: "management",
    html,
    count: filtered.length,
    missingCount: missingRolesPretty.length,
    debug_windowStart: windowStart.toISOString(),
    debug_windowEnd: windowEnd.toISOString(),
    debug_all_rows_seen: inspected.map(r => ({
      original: r[TS_COL],
      parsedISO: r.__parsedMs ? new Date(r.__parsedMs).toISOString() : null,
      role: r[DEPT_COL]
    })),
    debug_filtered_rows: filtered.map(r => ({
      original: r[TS_COL],
      parsedISO: r.__parsedMs ? new Date(r.__parsedMs).toISOString() : null,
      role: r[DEPT_COL]
    })),
    debug_filteredRoles: submittedRoles,
    debug_missingRoles: missingRolesPretty,
  }
});

// Follow-up items for missing roles only
for (const roleName of missingRolesPretty) {
  const to = DEPT_EMAIL[roleName] || "";
  outputItems.push({
    json: {
      type: "followup",
      role: roleName,
      to,
      subject: `Weekly Report Not Seen – ${roleName}`,
      bodyText: `<p>Hello ${roleName},</p>

<p>
Your weekly report was not seen in the reporting submissions for this week
(<strong>deadline: Friday 4:00 PM WAT</strong>).
</p>

<p>
Please reply to this email with the link to your weekly report.
</p>

<p>
Thank you.
</p>

<p>
<strong>Management,<br>
[Your Organization]</strong>
</p>`
    }
  });
}

return outputItems;

